function Header() {
  return (
    <header className="h-20 flex items-center px-6 bg-white border-b">
      <div className="flex w-full items-center">
        
        {/* Left - takes up 1 part of the space */}
        <div className="flex-1">
          <h1 className="text-xl font-semibold">Left</h1>
        </div>

        {/* Center - takes only needed space */}
        <div className="flex-none text-center">
          <h1 className="text-xl font-semibold">Center</h1>
        </div>

        {/* Right - takes up 1 part of the space, text aligned right */}
        <div className="flex-1 text-right">
          <h1 className="text-xl font-semibold">Right</h1>
        </div>

      </div>
    </header>
  );
}

export default Header;
